from pathlib import Path
R=Path(__file__).resolve().parents[2];U=R/'outputs/phase115/phase115_20261014';O=R/'src/research_results/phase115_20261014'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 pack=U/'reviewer_pack';template=json.loads((pack/'independent_adjudication_template.json').read_text(encoding='utf-8'));ids=[r['independent_id'] for r in template['records']]
 assert len(ids)==7 and all(r['point_candidate_class'] is None and r['status']=='not_reviewed' for r in template['records'])
 old=json.loads((O/'PACKAGE_SHA.json').read_text(encoding='utf-8'))
 for n,h in old['reviewer_artifacts_sha256'].items():assert sha(pack/n)==h,n
 assert not (U/'viewer_v1_snapshot').exists();(U/'viewer_v1_snapshot').mkdir();shutil.copyfile(pack/'index.html',U/'viewer_v1_snapshot/index.html');shutil.copyfile(pack/'README_FOR_REVIEWER.md',U/'viewer_v1_snapshot/README_FOR_REVIEWER.md')
 page="""<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>独立影像判读与填写</title><style>body{font-family:system-ui;margin:0;color:#17232b;background:#f4f6f8}header{padding:22px;background:white}main{padding:20px;max-width:1500px;margin:auto}.box{background:white;padding:18px;border-radius:8px;margin:18px 0}input,select,textarea,button{font:inherit;padding:8px;margin:5px}input{min-width:220px}textarea{display:block;width:96%;min-height:82px}button{cursor:pointer}.primary{background:#135ca4;color:white;border:0;padding:12px 18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}figure{margin:0;padding:8px;background:white}img{width:100%;cursor:zoom-in}nav{position:sticky;top:0;background:#f4f6f8;padding:8px;z-index:1}.hint{color:#58636b}#feedback{white-space:pre-line}label{display:inline-block;margin:4px}@media(max-width:800px){.grid{grid-template-columns:1fr}input{min-width:120px}}</style><header><h1>独立影像判读与填写</h1><p>看每点的近景与上下文，在图下填写。无法判断可如实选择。填写完成后点击“导出提交JSON”。</p></header><main><section class="box"><h2>审阅信息</h2><label>审阅者编号 <input id="reviewer" placeholder="可追溯编号；未知留空"></label><label>遥感判读经验 <input id="experience" placeholder="简短说明；未知留空"></label><label>是否接触过原参考或先前揭示 <select id="exposure"><option value="unknown">unknown／不确定</option><option value="no">否</option><option value="yes">是</option></select></label><p id="reviewType" class="hint"></p><p class="hint">身份未独立核验。实际提交时间只在点击导出时记录。</p><button class="primary" id="export">导出提交JSON</button><label>导入已保存JSON <input type="file" id="import" accept=".json"></label><p id="feedback"></p><p id="progress"></p></section><nav id="nav"></nav><h2 id="heading"></h2><p class="hint">黄色十字：原10m点；青色框：20m单元；灰色：无观测／影像外；粉色：饱和。固定TOA0—0.3映射，最近邻放大不增加细节。点击图可打开完整尺寸。</p><div id="images" class="grid"></div><section class="box"><h2>本点填写</h2><label>原10m点候选类别 <select id="point"><option value="">未填写</option><option>Cloud</option><option>落地云影</option><option>其他阴影或暗地表</option><option>混合</option><option>无法判断</option></select></label><label>所属20m单元 <select id="cell"><option value="">未填写</option><option>同质</option><option>混合</option><option>无法判断</option></select></label><p>具体可见依据（描述支持判断的影像特征）</p><textarea id="evidence" placeholder="记录可见依据；不要只填一个类别名称"></textarea><p>不确定性（若无明显不确定性，也请明确说明）</p><textarea id="uncertainty" placeholder="例如边界、分辨率、其他阴影类型或背景难区分"></textarea><label>现有上下文是否足够 <select id="context"><option value="unknown">unknown／未填写</option><option>足够</option><option>不足</option><option>无法判断</option></select></label><p id="rowStatus"></p><button id="previous">上一点</button><button id="next">下一点</button><button id="save">保存本点</button></section><p class="hint">浏览器内保存不等于文件提交。导出的文件名为independent_adjudication_submission.json。</p></main><script>
const IDS=__IDS__, TEMPLATE=__TEMPLATE__, KEY='phase115_adjudication_form_v2';
const $=id=>document.getElementById(id);let DATA=structuredClone(TEMPLATE),current=0;
const fields={point:'point_candidate_class',cell:'cell_20m_state',evidence:'visible_evidence',uncertainty:'uncertainty',context:'existing_context_sufficient'};
function validIds(x){return x&&Array.isArray(x.records)&&x.records.length===IDS.length&&x.records.every((r,i)=>r.independent_id===IDS[i])}
try{const saved=JSON.parse(localStorage.getItem(KEY));if(validIds(saved))DATA=saved}catch(e){}
function rowState(r){const has=[r.point_candidate_class,r.cell_20m_state,r.visible_evidence,r.uncertainty].some(Boolean);return r.point_candidate_class&&r.cell_20m_state&&r.visible_evidence&&r.visible_evidence.trim()&&r.uncertainty&&r.uncertainty.trim()&&r.existing_context_sufficient&&r.existing_context_sufficient!=='unknown'?'reviewed':has?'draft':'not_reviewed'}
function refresh(){const complete=DATA.records.filter(r=>r.status==='reviewed').length;$('progress').textContent=`已完整填写 ${complete}/7；其他记录保留草稿或未填写状态。`;$('nav').replaceChildren(...IDS.map((id,i)=>{const b=document.createElement('button');b.textContent=id+' '+({reviewed:'已填写',draft:'草稿',not_reviewed:'未填写'}[DATA.records[i].status]||'');b.addEventListener('click',()=>{save();show(i)});return b}));$('reviewType').textContent=DATA.has_seen_original_reveal==='yes'?'已接触原揭示：此次只能作为事后复核。':DATA.has_seen_original_reveal==='no'?'记录为未接触原揭示；经验与身份仍按提供资料如实记账。':'接触史未知：不能据此认定为新的独立盲审。'}
function save(){const r=DATA.records[current];for(const [id,f] of Object.entries(fields))r[f]=$(id).value||null;r.existing_context_sufficient=r.existing_context_sufficient||'unknown';r.status=rowState(r);DATA.reviewer_id=$('reviewer').value.trim()||'unknown';DATA.reviewer_experience=$('experience').value.trim()||'unknown';DATA.has_seen_original_reveal=$('exposure').value;DATA.identity_verification='unknown';try{localStorage.setItem(KEY,JSON.stringify(DATA));$('feedback').textContent='已保存到当前浏览器。请导出JSON文件交付。'}catch(e){$('feedback').textContent='浏览器未允许本地保存，请导出JSON保留填写内容。'}$('rowStatus').textContent=r.status==='reviewed'?'本点字段已填写；尚未封存。':r.status==='draft'?'本点为草稿，有字段未提供。':'本点尚未填写。';refresh()}
function show(i){current=i;const r=DATA.records[i];$('heading').textContent=IDS[i];$('reviewer').value=DATA.reviewer_id==='unknown'?'':DATA.reviewer_id||'';$('experience').value=DATA.reviewer_experience==='unknown'?'':DATA.reviewer_experience||'';$('exposure').value=DATA.has_seen_original_reveal||'unknown';for(const [id,f] of Object.entries(fields))$(id).value=r[f]||'';$('context').value=r.existing_context_sufficient||'unknown';$('images').innerHTML=[[640,'RGB','640m／原生10m RGB'],[640,'FALSE','640m／原生20m NIR/R/G'],[10240,'RGB','10.24km／原生10m RGB'],[10240,'FALSE','10.24km／原生20m NIR/R/G']].map(([w,k,title])=>`<figure><figcaption>${title}</figcaption><a href="assets/${IDS[i]}_${w}_${k}.png" target="_blank"><img alt="${IDS[i]} ${title}" src="assets/${IDS[i]}_${w}_${k}.png"></a></figure>`).join('');$('rowStatus').textContent=r.status==='reviewed'?'本点字段已填写；尚未封存。':r.status==='draft'?'本点为草稿，有字段未提供。':'本点尚未填写。';refresh()}
function exportData(){save();const result=structuredClone(DATA);result.actual_submitted_at=new Date().toISOString();const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='independent_adjudication_submission.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);$('feedback').textContent='已导出independent_adjudication_submission.json。请把文件放回本轮文件夹交付。'}
$('export').addEventListener('click',exportData);$('save').addEventListener('click',save);$('previous').addEventListener('click',()=>{save();show(Math.max(0,current-1))});$('next').addEventListener('click',()=>{save();show(Math.min(IDS.length-1,current+1))});
for(const id of [...Object.keys(fields),'reviewer','experience','exposure'])$(id).addEventListener('change',save);
$('import').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file)return;const x=JSON.parse(await file.text());if(!validIds(x))throw Error('匿名编号或记录数不匹配');DATA=structuredClone(x);for(const r of DATA.records)r.status=rowState(r);show(0);try{localStorage.setItem(KEY,JSON.stringify(DATA))}catch(e){}$('feedback').textContent='已导入填写内容，缺项仍保留。'}catch(e){$('feedback').textContent='无法导入：'+e.message}});show(0);
</script></html>"""
 page=page.replace('__IDS__',json.dumps(ids)).replace('__TEMPLATE__',json.dumps(template,ensure_ascii=False))
 assert not re.search(r'\b(FN|FP|Omni|Source|group_id|product_id|sampling_layer|shadow_confidence|A[0-9]{3})\b',page)
 (pack/'index.html').write_text(page,encoding='utf-8',newline='\n')
 (pack/'README_FOR_REVIEWER.md').write_text('# 网页填写说明\n\n用浏览器打开index.html，在顶部填写审阅信息，再逐点选择类别、20m单元状态，填写具体依据、不确定性及上下文是否足够。未知保留unknown，无法判断如实选择。点击保存本点及下一点；最后点击导出提交JSON。\n\n导出文件名为independent_adjudication_submission.json。浏览器内保存不等于提交，请交付该JSON。实际时间只在点击导出时记录；身份核验保持unknown。已接触原揭示的填写仅为事后复核，不能称新的独立盲审。\n',encoding='utf-8',newline='\n')
 for n,h in old['reviewer_artifacts_sha256'].items():
  if n.startswith('assets/') or n=='independent_adjudication_template.json':assert sha(pack/n)==h,n
 assert sha(U/'independent_review_pack.zip')==old['archive_sha256']
 with zipfile.ZipFile(U/'independent_review_pack_v2.zip','x',compression=zipfile.ZIP_DEFLATED) as z:
  for p in sorted(pack.rglob('*')):
   if p.is_file():z.write(p,p.relative_to(pack).as_posix())
 info={'version':2,'scope':'form interface only; cases/order/pixels/display/template unchanged','archive_sha256':sha(U/'independent_review_pack_v2.zip'),'archive_bytes':(U/'independent_review_pack_v2.zip').stat().st_size,'previous_archive_unchanged':True,'previous_index_sha256':sha(U/'viewer_v1_snapshot/index.html'),'artifacts_sha256':{p.relative_to(pack).as_posix():sha(p) for p in pack.rglob('*') if p.is_file()},'independent_opinions_created':0}
 (O/'PACKAGE_SHA_V2.json').write_text(json.dumps(info,indent=2)+'\n',encoding='utf-8',newline='\n')
 shutil.copyfile(O/'PACKAGE_SHA_V2.json',U/'PACKAGE_SHA_V2.json');print('Form interface generated; fixed7 cases and28 images unchanged; independent opinions0')
if __name__=='__main__':main()
